use xiom.io;

type Item = {
  name: Str;
  price: Float64;
  stock: Int;
}

enum VendResult {
  Success(item: Str, change: Float64),
  OutOfStock,
  InsufficientFunds,
}

fn vend(item: Item, money: Float64) -> VendResult {
  if item.stock <= 0 {
    return VendResult.OutOfStock;
  }
  if money < item.price {
    return VendResult.InsufficientFunds;
  }
  let change = money - item.price;
  return VendResult.Success(item.name, change);
}

fn describe_vend(r: VendResult) -> Str {
  match r {
    Success(name, change) => { return "Enjoy your " + name + "! Change: $" + change; }
    OutOfStock => { return "Sorry, out of stock."; }
    InsufficientFunds => { return "Please insert $" + /* more needed */ " more."; }
  }
}

fn main() -> Int {
  var item = Item{ name: "Cookie"; price: 1.00; stock: 2; };
  let r1 = vend(item, 1.00);
  item.stock = item.stock - 1;
  let r2 = vend(item, 1.00);
  item.stock = item.stock - 1;
  let r3 = vend(item, 1.00);
  var sold_out = 0;
  match r3 { OutOfStock => { sold_out = 1; } _ => {} }
  return sold_out;
}
